mapper.update:
UPDATE coupon_seckill_refund
SET status = 'APPROVING', update_time = #{now}
WHERE id = #{id} AND status = 'REVIEWING'

UPDATE coupon_seckill_refund
SET status = 'REFUNDED', refund_time = #{now}, update_time = #{now}
WHERE id = #{id} AND status = 'APPROVING'

UPDATE coupon_seckill_refund
SET status = 'REJECTED', merchant_remark = #{merchantRemark}, update_time = #{now}
WHERE id = #{id} AND status = 'REVIEWING'

mapper.select:
SELECT r.id, r.refund_no, r.seckill_order_id, o.order_no, o.coupon_name, r.user_id, u.name AS user_name, u.phone, r.coupon_user_id, r.refund_amount, r.status, r.reason, r.images, r.merchant_remark, r.create_time, r.refund_time FROM coupon_seckill_refund r LEFT JOIN coupon_seckill_order o ON o.id = r.seckill_order_id LEFT JOIN `user` u ON u.id = r.user_id
r.status = #{status}
ORDER BY r.id DESC LIMIT #{offset}, #{pageSize}

SELECT COUNT(*)
FROM coupon_seckill_refund r


        r.status = #{status}
